scr.script:
			/*
variable ddlStatementsList should be used to return the list with DDL statements
that are created by script - as shown below:
ddlStatementsList.add(new java.lang.String(ddl));
other available variables:
- model - relational model instance
- pModel - physical model instance
- table - the table in relational model
- tableProxy - table definition in physical model
*/
var ddl;
var lname;
//journal table name suffix
jnTabSuf = "_JN";
// trigger name suffix
jnTrgSuf = "_JNtrg";
prompt = model.getAppView().getSettings().isIncludePromptInDDL();
useSchema = model.getAppView().getSettings().isIncludeSchemaInDDL();
if(model.getStorageDesign().isOpen()){
	if(useSchema){
	     lname = tableProxy.getLongName();
	}else{
		lname = tableProxy.getName();
	}
}else{
	if(useSchema){
	     lname = table.getLongName();
	}else{
		lname = table.getName();
	}
}
if(prompt){
	ddl= "PROMPT Creating Journal Table for '"+lname+"';\n";
}else{
	ddl = "";
}
ddl = ddl + "CREATE TABLE "+lname+jnTabSuf+"\n"+
" (JN_OPERATION CHAR(3) NOT NULL"+"\n"+
" ,JN_ORACLE_USER VARCHAR2(30) NOT NULL"+"\n"+
" ,JN_DATETIME DATE NOT NULL"+"\n"+
" ,JN_NOTES VARCHAR2(240)"+"\n"+
" ,JN_APPLN VARCHAR2(35)"+"\n"+
" ,JN_SESSION NUMBER(38)"+"\n";
cols = table.getElements();
for(var i=0;i<cols.length;i++){
	col = cols[i];
	ddl = ddl +" ,"+col.getName()+" "+col.getDatatypeString();
	if(col.isMandatory()){
		ddl = ddl + " NOT NULL\n";
	}else{
		ddl = ddl + "\n";
	}
}
ddl = ddl + " );";
ddlStatementsList.add(new java.lang.String(ddl));
if(prompt){
	ddl= "\nPROMPT Creating Journal Trigger for '"+lname+"';\n";
}else{
	ddl = "\n";
}
ddl = ddl +
"CREATE OR REPLACE TRIGGER "+lname+jnTrgSuf +"\n"+
"  AFTER \n" +
"  INSERT OR \n" +
"  UPDATE OR \n" +
"  DELETE ON "+lname+" for each row \n" +
" Declare \n" +
"  rec "+lname+"_JN"+"%ROWTYPE; \n" +
"  blank "+lname+"_JN"+"%ROWTYPE; \n" +
"  BEGIN \n" +
"    rec := blank; \n" +
"    IF INSERTING OR UPDATING THEN \n" ;
for(var i=0;i<cols.length;i++){
	col = cols[i];
	ddl = ddl + "      rec."+col.getName()+" := :NEW."+col.getName()+"; \n";
}
ddl = ddl +
"      rec.JN_DATETIME := SYSDATE; \n" +
"      rec.JN_ORACLE_USER := SYS_CONTEXT ('USERENV', 'SESSION_USER'); \n" +
"      rec.JN_APPLN := SYS_CONTEXT ('USERENV', 'MODULE'); \n" +
"      rec.JN_SESSION := SYS_CONTEXT ('USERENV', 'SESSIONID'); \n" +
"      IF INSERTING THEN \n" +
"        rec.JN_OPERATION := 'INS'; \n" +
"      ELSIF UPDATING THEN \n" +
"        rec.JN_OPERATION := 'UPD'; \n" +
"      END IF; \n" +
"    ELSIF DELETING THEN \n" ;
for(var i=0;i<cols.length;i++){
	col = cols[i];
	ddl = ddl + "      rec."+col.getName()+" := :OLD."+col.getName()+"; \n";
}
ddl = ddl +
"      rec.JN_DATETIME := SYSDATE; \n" +
"      rec.JN_ORACLE_USER := SYS_CONTEXT ('USERENV', 'SESSION_USER'); \n" +
"      rec.JN_APPLN := SYS_CONTEXT ('USERENV', 'MODULE'); \n" +
"      rec.JN_SESSION := SYS_CONTEXT ('USERENV', 'SESSIONID'); \n" +
"      rec.JN_OPERATION := 'DEL'; \n" +
"    END IF; \n" +
"    INSERT into "+lname+"_JN"+" VALUES rec; \n" +
"  END; \n" +
"  /"
ddlStatementsList.add(new java.lang.String(ddl));

			var index;
// define function - function parameter doesn't need to be named index
function checkFKColumns(index){
  //check it's foreign key index, otherwise FK is null
 if(index.isFK()){
 	if(!index.getFKAssociation().isMandatory()){
	 cols = index.getElements();
	 for(var i=0;i<cols.length;i++){
		if(cols[i].isMandatory()){
			return false;
		}
	 }
 	}
 }
 return true;
}
// invoke the function
checkFKColumns(index);

						//scripts to handle translation of model
				var CODEVERSION = '1.5'
				var gLogNote = "LOG";
				var gParams={}
			// Translation
				var gTranslInforegexp =/TRANSLATION\{([^}]*)\}/;
				var translation = false
				var NOTESSTARTTAG = '[<tag>[';
				var NOTESENDTAG = ']<tag>]';
				var CURRENTLANG = "currentLang"
				var VERSION = "version"
				var LASTSYNC = "lastSync"
				var LANGUAGES = "languages"
				var DEEPLAUTHKEY = "DEEPLAuthKey"

				var logInitialized = false;

			// message
				var PLAINMESSAGE = 1;
				var ERRORMESSAGE = 0;
				var WARNINGMESSAGE = 2;
				var QUESTIONMESSAGE = 3;


				var DEEPLURL = "https://api.deepl.com/v2/translate"
				var DEEPLURL_usage = "https://api.deepl.com/v2/usage"

				function fullmessage(msg,type) {
					Java.type("javax.swing.JOptionPane").showMessageDialog(null
					, msg,'ODM-Translation', type);
				}

				function error(msg) {
					fullmessage(msg,ERRORMESSAGE);
					}
				function message(msg) {
					fullmessage(msg,PLAINMESSAGE);
					}

					function getCurrentLang() {return gParams[CURRENTLANG];}
					function setCurrentLang(lang) {gParams[CURRENTLANG] = lang;}
					function getVersion() {return gParams[VERSION];}
					function setVersion(version) {gParams[VERSION] = version;}
					function getLastSync() {return gParams[LASTSYNC];}
					function setLastSync(lastSync) {gParams[LASTSYNC] = lastSync;}
					function getLanguages() {return gParams[LANGUAGES];}
					function setLanguages(langs) {gParams[LANGUAGES] = langs;}
					function getLangArr() {return getLanguages().split(',');}
					function getDEEPLAuthKey() {
						 if (DEEPLAUTHKEY in gParams) {return gParams[DEEPLAUTHKEY]}
						 else {return null}
					}
//DEBUG
					function setDEEPLAuthKey(key) {gParams[DEEPLAUTHKEY] = key; message("setdeeplauthkey:"+key)}

			function linemessage() {
				str = ''
				for (i=0;i<arguments.length;i++){
					str = str.concat(arguments[i],'\n')
				}
				Java.type("javax.swing.JOptionPane").showMessageDialog(null, str, 'Testjs', 1);
			}

			function translconn(purl){
				URL =  Java.type("java.net.URL")
				url = new URL(purl)
				con = url.openConnection();
				con.setRequestMethod("GET");
				con.setRequestProperty("Content-Type", "application/json; utf-8");
				con.setRequestProperty("Accept", "application/json");
				con.setRequestProperty("Accept-Charset", "utf-8");
				con.setDoOutput(true);
				return con
				//try {os = con.getOutputStream()}
				//	catch (err){message("os= "+err.toString())}
				//var mybuffer = [];
				//try {os.write(mybuffer,0,mybuffer.length)
				//	}
				//	catch (err){message('write='+err.toString())}
			}

			function Utf8ArrayToStr(array) {
			  var out, i, len, c;
			  var char2, char3;

			  out = "";
			  len = array.length;
			  i = 0;
			  while (i < len) {
			    c = array[i++];
			    switch (c >> 4)
			    { 
			      case 0: case 1: case 2: case 3: case 4: case 5: case 6: case 7:
			        // 0xxxxxxx
			        out += String.fromCharCode(c);
			        break;
			      case 12: case 13:
			        // 110x xxxx   10xx xxxx
			        char2 = array[i++];
			        out += String.fromCharCode(((c & 0x1F) << 6) | (char2 & 0x3F));
			        break;
			      case 14:
			        // 1110 xxxx  10xx xxxx  10xx xxxx
			        char2 = array[i++];
			        char3 = array[i++];
			        out += String.fromCharCode(((c & 0x0F) << 12) |
			                                   ((char2 & 0x3F) << 6) |
			                                   ((char3 & 0x3F) << 0));
			        break;
			    }
			  }    
			  return out;
			}
			function getanswer(inputstr){
				var buf = []
				var b = inputstr.read()
				while (b != -1) {
					buf.push(b)
					b = inputstr.read()
				}
				return Utf8ArrayToStr(buf)
			}

			function haveDeeplAccess(){
				var urlu = DEEPLURL_usage+"?auth_key="+getDEEPLAuthKey()
				var conu = translconn(urlu)

				try {
					s = getanswer(conu.getInputStream())
					json = JSON.parse(s)
					//message2(urlu,JSON.stringify(json))
					return true
				}
				catch (err){return false}
			}

			function translate(fromlang,tolang,text){
				var url = DEEPLURL
					+"?auth_key="+getDEEPLAuthKey()
					+"&text="+encodeURI(text)
					+"&target_lang="+tolang
					+"&source_lang="+fromlang
				var con = translconn(url)

				try {
					s = getanswer(con.getInputStream())
					json = JSON.parse(s)
					//message2(url,JSON.stringify(json))
					return json["translations"][0]["text"]
				}
				catch (err){message(err.toString())}
			}

				function initLog(){
					if (! logInitialized){
						var lNote = model.getNoteSet().getByName(gLogNote);
				     	if (lNote == null) {
				    	    		lNote = model.createNote()
					    		lNote.setName(gLogNote);
				     	}
				     	lNote.setComment("");
				     	logInitialized = true;
					}
				}
				function log(plog){
					initLog();
					var lNote = model.getNoteSet().getByName(gLogNote);
				     lNote.setComment(lNote.getComment()+"\n"+plog);
				}

				function getTranslInfo(){
					lDesignComment = model.design.getComment();
				     lparam= lDesignComment.match(gTranslInforegexp);
				     if (lparam != null) {
				     	lparam=trim(lparam[1])
						lparlines = lparam.split("\n")
						for (l=0;l<lparlines.length;l++){
				     		vals=lparlines[l].split("=")
				     		if (vals[0] != null && vals[0] != "") {  
				     			gParams[vals[0]] = trim(vals[1])
				     		}
						}
//DEBUG
					linemessage('getTranslInfo',lDesignComment,lparam,gParams.length,JSON.stringify(gParams))
						//linemessage(JSON.stringify(gParams))
					}    
				}	
				function param2comment(){
					retval = "TRANSLATION{\n"+CURRENTLANG+"="+getCurrentLang()
									+"\n"+LANGUAGES+"="+getLanguages()
									+"\n"+LASTSYNC+"="+getLastSync()
									+"\n"+VERSION+"="+getVersion()
					deeplkey = getDEEPLAuthKey()			
					if (deeplkey != null) {retval += "\n"+DEEPLAUTHKEY+"="+deeplkey}
					retval += "\n}"
//DEBUG
					message("param2comment:"+retval)
				 	return retval
				}
				function setTranslInfo() {
					setLastSync(curDateStr())
					curComment = model.design.getComment();
					lparam= curComment.match(gTranslInforegexp);
					if (lparam == null) {model.design.setComment(curComment + param2comment())}
					else {model.design.setComment(
						curComment.replace(gTranslInforegexp,param2comment()));
					}
				}

				function buildRegExpTag(innertag,tag){
					return tag.replace('<tag>',innertag).replace(/\[/g,'\\[').replace(/\]/g,'\\]')
				}

				function trim(str){
					return str.replace(/^[\s]+|[\s]+$/g,'');
				}

				function textFromNote(tag,obj) {
			    	note = obj.getNotes()
			    	restart =  buildRegExpTag(tag, NOTESSTARTTAG)
			    	reend =  buildRegExpTag (tag, NOTESENDTAG)+"[\n]*"
			    	re = new RegExp(restart + '([^]*)' + reend)
			    	ma = note.match(re)
			    	retval = ''
				   	if (ma != null) {
						//linemessage("|"+reend+"|\n"+"|"+ma[0]+"|")
				   		retval = trim(ma[1])
					}
					return retval
				}

				function textToNote(tag,obj,value) {
			    	note = obj.getNotes()
			    	restart =  buildRegExpTag(tag, NOTESSTARTTAG)
			    	reend =  buildRegExpTag (tag, NOTESENDTAG)+"[\n]*"
			    	re = new RegExp(restart + '([^]*)' + reend)
			    	ma = note.match(re)
					newentry = NOTESSTARTTAG.replace('<tag>',tag)+'\n' 
						+ value 
						+'\n' + NOTESENDTAG.replace('<tag>',tag)
						+'\n'
				   	if (ma == null) {
				   		note = note + newentry
					} else {
						//message("|"+newentry+"|\n"+"|"+ma[0]+"|")
						note = note.replace(ma[0] , newentry)
					}
					obj.setNotes(note)
				}

				function init(istUpgrade){
					getTranslInfo();
					if (gParams.length == 0) {
						throw new Error("\n***TRANSLATION not installed***\n");
					}
					if (getVersion() != CODEVERSION && !istUpgrade) {
						msg = "\n***TRANSLATION version mismatch: "
							+"expected " + CODEVERSION + " found "+getVersion()
							+"\nPlease upgrade.***\n"
						throw new Error(msg);
					}
					translation = false
					if (getDEEPLAuthKey() != null && getDEEPLAuthKey() != ''){
						translation = haveDeeplAccess()
					}
				}

				function doLangValue(propName,obj,value,isNote,notNull){
					lpropName = getCurrentLang() + propName;
					oldval = (isNote) ? textFromNote(lpropName,obj) : obj.getProperty(lpropName);
					langArr = getLangArr()

					//DEBUG
					if (((obj.getName() == '') && (propName == ''))
					     || (obj.getName() == '')) {
						message('Obj-Name='+obj.getName()+ '  '+propName);
						display = true;
					} else display = false;

					for (il=0;il<langArr.length;il++) {
						// nur die fremden Sprachen ersetzen
						flang = langArr[il]
						if (flang != getCurrentLang()) {
							// if value contains *xx*, don't add another one
							if (value.match(/^\*[A-Z]{2}\* /)) {
									nontranslateprefix =  ''
								} else {
									nontranslateprefix =  '*'+getCurrentLang()+'* '			
								}
							//markiere oder fülle die fremde Properties
							fpropName = flang + propName;
							fprop = (isNote) ? textFromNote(fpropName,obj) : obj.getProperty(fpropName);
							// Die Reihenfolge der folgenden IF ist wichtig!
							// Falls die Fremdsprache noch automtaisch übersetzt ist ( *XX* vorneweg hat), überschreibe sie
							if (fprop.match(/^\*[A-Z]{2}\* /)) {
								// nicht übersetzter alter Wert. Falls Translation und
								// der Wert stammt von früherer Nichtübersetung aus der current Lang, 
								// versuchen ihn zu übersetzen. Sonst markiere ihn wieder als nicht übersetzt *XX*
								re = new RegExp("^\\*"+getCurrentLang()+"\\* ");
								if (translation && (fprop.match(re))){
									try {newvalue = '**'+translate(getCurrentLang(),flang,value)}
									catch (err) {newvalue = nontranslateprefix+value}
								} else {newvalue = nontranslateprefix+value}
								if (isNote) textToNote(fpropName,obj,newvalue);  
									else obj.setProperty(fpropName,newvalue);
								} else if (fprop.startsWith('**')) {
									// ** wurde automatisch übersetzt. Falls Originallang geändert hat, übersetze neu
									if (value != oldval && ! oldval.startsWith('*')) {
										if (translation){
											try {newvalue = '**'+translate(getCurrentLang(),flang,value)}
											catch (err) {newvalue = nontranslateprefix+value}
											if (isNote) textToNote(fpropName,obj,newvalue);  
											else obj.setProperty(fpropName,newvalue);
										}
									}									
								} else if (fprop.startsWith('*')) {
									// * sind in Bearbeitung nichts ersetzen
							} else if (fprop == "" && value == "" && ! notNull) {
								// das Ziel ist leer, der neue Wert auch und es ist kein Mussfeld. lass das Ziel leer
							} else if (fprop == "") {
								// das Ziel ist leer aber aus einem Grund muss ich es überschreiben (siehe vorheriges IF)
								// übersetze den Text. Falls es schief geht, mach daraus einen *XX* Text
								if (translation){
									try {newvalue = '**'+translate(getCurrentLang(),flang,value)}
									catch (err) {newvalue = nontranslateprefix+value}
								}else {newvalue = nontranslateprefix+value}
								if (isNote) textToNote(fpropName,obj,newvalue);  
									else obj.setProperty(fpropName,newvalue);
						    } else {
								// das Ziel ist gefüllt (haben wir schon abgefragt), 
								// nicht in Bearbeitung und nicht automatisch übersetzt (* am Anfang haben wir schon abgefragt)
								// d.h. es hat einen gültigen Wert. 
								// Markiere es, falls die Quelle wirklich geändert hat (gegenüber dem current-Lang-Property)
								if (value != oldval && ! oldval.startsWith('*') && ! fprop.startsWith('*')) {
									  // die Quelle hat geändert 
									  // und war selber nicht ein Feld, das vor der Änderung einen * am Anfang hatte
									  // und der foreign Wert hat noch kein * am Anfang
									  // Markiere die foreign property
									  if (isNote) textToNote(fpropName,obj,"*"+fprop);
								   		else obj.setProperty(fpropName,"*"+fprop)
								}
							}
						}
					}
					// die Werte der CurrentLang kommen aus dem Objekt, überschreibe die Übersetzungsproperties immer
					if (isNote) textToNote(lpropName,obj,value);
					   else obj.setProperty(lpropName, value);
				}

				function doProperty(propName,obj,value,notNull){
					doLangValue(propName,obj,value,false,notNull);
				}

				function doNote(propName,obj,value) {
					doLangValue(propName,obj,value,true,false);
				}

				function fuellUDP(tolang){
					entities = model.getEntitySet().toArray();
					for (ie=0;ie<entities.length;ie++) { //
						ent = entities[ie];
						//DEBUG
//						if (!((ent.getName() == 'Test-Entität') || ent.getName().endsWith('Test Entity') || ent.getName().endsWith('Entité test'))) continue;

						doProperty("_ENTI_NAME",ent,ent.getName(),true)
						doNote("_ENTI_COMMENT",ent,ent.getComment())
						doProperty("_ENTI_SYNONYM",ent,ent.getSynonym(),false)

						if (tolang != null){
							ent.setName(ent.getProperty(tolang+"_ENTI_NAME"));
							ent.setComment(textFromNote(tolang+"_ENTI_COMMENT",ent))
							ent.setSynonym(ent.getProperty(tolang+"_ENTI_SYNONYM"));
						}


						attrs = ent.getAttributes().toArray();
						//log("Attrs="+attrs.length)
						for (ia=0;ia<attrs.length;ia++) { //
							attr = attrs[ia];
							doProperty("_ATTR_NAME",attr,attr.getName(),true);
							doNote("_ATTR_COMMENT",attr,attr.getComment());			

							if (tolang != null){
								attr.setName(attr.getProperty(tolang+"_ATTR_NAME"));
								attr.setComment(textFromNote(tolang+"_ATTR_COMMENT",attr))
							}
						}
						ent.setDirty(true);
					}
					relationships = model.getRelationSet().toArray();
					for (ir=0;ir<relationships.length;ir++) { //
						rel = relationships[ir];
						//DEBUG
						if (rel.getName() == '') linemessage(rel.getName(),rel.getNameOnSource());

						doProperty("_RELA_TEXT_FROM",rel,rel.getNameOnSource(),false)
						doProperty("_RELA_TEXT_TO",rel,rel.getNameOnTarget(),false)	

						if (tolang != null){
							rel.setNameOnSource(rel.getProperty(tolang+"_RELA_TEXT_FROM"));
							rel.setNameOnTarget(rel.getProperty(tolang+"_RELA_TEXT_TO"));
						}
						if (rel.getName() == '') linemessage('nachher',rel.getName(),rel.getNameOnSource());
						rel.setDirty(true);
					}
				}

				function curDateStr(){
					var currentdate = new Date();
					return  currentdate.getDate() 
					+ "/" + (currentdate.getMonth()+1) 
					+ "/" + currentdate.getFullYear() + "  " 
					+ currentdate.getHours() + ":" 
					+ currentdate.getMinutes() + ":" + currentdate.getSeconds();
				}

				function setLabels(what){
					views =	model.getDesign().getLogicalDesign().getListOfSubviews() 
					for (vv=0;vv<views.length;vv++){
						view = views[vv]
//						linemessage(view.getName(),view.showLabels(),what)
						view.setShowLabels(what)
					}
				}

				function changeLang(pfromLang,ptoLang){
					//log("3:"+getLanguages());
				//	log("change from " + pfromLang + " to " + ptoLang);
					fuellUDP(ptoLang);
					setCurrentLang(ptoLang);
					setTranslInfo();	
					model.design.setDirty(true);
				}

				function initTranslation() {
					getTranslInfo()
					if (gParams == null || gParams.length == 0) {
						setCurrentLang('DE')
						setLanguages('DE,EN')
						setVersion(åCODEVERSION)
					} else {
					linemessage("initTranslation",gParams.length)
						throw new Error("\n***TRANSLATION ("+getVersion()+") already installed***\n");
					}
					//hier gibt es einen Eintrag für die Translation
					init();

					fuellUDP(null);

					setTranslInfo()
					model.design.setDirty(true);
					message ("TRANLSATION installed current-language="+getCurrentLang()
					         + " languages="+getLanguages()+" version="+getVersion()
						        ,PLAINMESSAGE);
				}

				function changeLanguage() {
					init();
					options = [];
					langchangefrom = getCurrentLang()
					langArr = getLangArr()
					for (il=0;il<langArr.length;il++) {
						if (langArr[il] != langchangefrom) {
							options.push(getCurrentLang() + '->' + langArr[il])
						}
					}
					if (options.length == 1) {
						antwort = options[0]
					} else {
						antwort = Java.type("javax.swing.JOptionPane").showInputDialog(null, 
				        	"Choose language change",
							"Change language",
							QUESTIONMESSAGE,
							null, 
							options, 
							options[0]);
					}
			        if (antwort != null){
						toLang = antwort.substr(-2)
						//Java.type("javax.swing.JOptionPane").showMessageDialog(null, antwort+'|'+toLang);
						changeLang(getCurrentLang(),toLang);
						message ("Model language changed from "+langchangefrom+" to "+toLang+"."
						        ,PLAINMESSAGE);
						setLabels(false)
						setLabels(true)
					}
				}

				function upgrade09_to_10() {
					// move comments from properties to comments
					entities = model.getEntitySet().toArray();
					for (ie=0;ie<entities.length;ie++) { 
						ent = entities[ie];
						langArr = getLangArr()
						for (il=0;il<langArr.length;il++) {
							// nur die fremden Sprachen ersetzen
							lang = langArr[il];
							textToNote(lang+"_ENTI_COMMENT",ent,ent.getProperty(lang+"_ENTI_COMMENT"));

							attrs = ent.getAttributes().toArray();
