				function upgradeTranslation () {
					init(true);				
					//1.0 has no upgrades
					if (getVersion()  == CODEVERSION) {
						message("TRANSLATE: latest version ("+getVersion()+") is installed")
					} else {
						upgraded = false
						if (getVersion() == "0.9") {
							upgrade09_to_10();
							upgraded = true
						}
						if (getVersion() == "1.0") {
							upgrade10_to_11();
							upgraded = true
						}
						if (getVersion() == "1.1") {
							upgrade11_to_12();
							upgraded = true
						}
						if (getVersion() == "1.2") {
							upgrade12_to_13();
							upgraded = true
						}
						if (getVersion() == "1.3") {
							upgrade13_to_14();
							upgraded = true
						}
						if (getVersion() == "1.4") {
							upgrade14_to_15();
							upgraded = true
						}
						if (upgraded) {
							setVersion(CODEVERSION)
							setTranslInfo();	
							message("TRANSLATE: latest version ("+CODEVERSION+") is now installed")
						} else {
						error("\nTRANSLATE: unknown version ("+getVersion()+").\n"
								+"Please contact support\n");
						}
					}			
				}

						//scripts to handle translation of model
