				function param2comment(){
					retval = "TRANSLATION{\n"+CURRENTLANG+"="+getCurrentLang()
									+"\n"+LANGUAGES+"="+getLanguages()
									+"\n"+LASTSYNC+"="+getLastSync()
									+"\n"+VERSION+"="+getVersion()
